-- 0001 — Phase 1 schema (PRD §13, ARCHITECTURE §11, S2-01).
--
-- Conventions
-- - IDs are prefixed ULIDs generated by the application (ARCHITECTURE §11.2), stored as text.
-- - Every tenant table has `workspace_id` (AGENTS §3 rule 5) and row-level security keyed on the
--   transaction setting `app.workspace_id` (§11.3). The data-access layer sets it with SET LOCAL;
--   without it, a query sees and writes nothing.
-- - FORCE ROW LEVEL SECURITY: the application role owns these tables (it runs the migrations), and
--   owners would otherwise bypass the policies.
-- - Children of a meeting reference (meeting_id, workspace_id) together, so a row can never point
--   at another workspace's meeting even if application code passes the wrong ID.
-- - Closed value sets are text + CHECK (easier to extend than enum types); values match
--   `shared/contracts`.

CREATE FUNCTION app_workspace_id() RETURNS text
  LANGUAGE sql STABLE
  AS $$ SELECT nullif(current_setting('app.workspace_id', true), '') $$;

-- Sign-in only: the Google subject being signed in, and the signed-in user (see the policies on
-- users and memberships below).
CREATE FUNCTION app_google_sub() RETURNS text
  LANGUAGE sql STABLE
  AS $$ SELECT nullif(current_setting('app.google_sub', true), '') $$;

CREATE FUNCTION app_user_id() RETURNS text
  LANGUAGE sql STABLE
  AS $$ SELECT nullif(current_setting('app.user_id', true), '') $$;

CREATE FUNCTION touch_updated_at() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END $$;

-- ---------- identity and tenancy ----------

CREATE TABLE workspaces (
  id          text PRIMARY KEY,
  name        text NOT NULL,
  plan        text NOT NULL DEFAULT 'free' CHECK (plan IN ('free')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

-- Users exist across workspaces, so this table has no workspace_id (PRD §13 exception). A row is
-- visible only to its own sign-in (`app.google_sub`) or to the signed-in user (`app.user_id`).
CREATE TABLE users (
  id            text PRIMARY KEY,
  google_sub    text NOT NULL UNIQUE,
  email         text NOT NULL,
  display_name  text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE memberships (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  user_id       text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role          text NOT NULL DEFAULT 'owner' CHECK (role IN ('owner')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, user_id)
);
CREATE INDEX memberships_user_idx ON memberships (user_id);

CREATE TABLE user_settings (
  id                        text PRIMARY KEY,
  workspace_id              text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  user_id                   text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  transcript_language_mode  text NOT NULL DEFAULT 'auto'
                            CHECK (transcript_language_mode IN ('auto', 'english', 'hindi', 'hinglish')),
  summary_language          text NOT NULL DEFAULT 'english'
                            CHECK (summary_language IN ('english', 'hindi', 'hinglish')),
  hindi_script              text NOT NULL DEFAULT 'roman' CHECK (hindi_script IN ('roman', 'devanagari')),
  retention_policy          text NOT NULL DEFAULT '7d' CHECK (retention_policy IN ('immediate', '7d', '30d')),
  record_video              boolean NOT NULL DEFAULT true,
  video_quality             text NOT NULL DEFAULT 'standard' CHECK (video_quality IN ('standard', 'data_saver')),
  consent_mode              text NOT NULL DEFAULT 'one_click'
                            CHECK (consent_mode IN ('one_click', 'automatic', 'off')),
  consent_message           text CHECK (char_length(consent_message) <= 1000),
  consent_acknowledged_at   timestamptz,
  follow_meet_mute          boolean NOT NULL DEFAULT true,
  offer_prompt              boolean NOT NULL DEFAULT true,
  default_template          text NOT NULL DEFAULT 'general'
                            CHECK (default_template IN ('general', 'standup', 'client_call', 'interview', 'one_on_one')),
  analytics_opt_out         boolean NOT NULL DEFAULT false,
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, user_id)
);

-- ---------- meetings and recordings ----------

CREATE TABLE meetings (
  id                     text PRIMARY KEY,
  workspace_id           text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  -- The capture session that produced the meeting (StartSessionResponse.sessionId).
  session_id             text NOT NULL UNIQUE,
  platform               text NOT NULL CHECK (platform IN ('google_meet')),
  external_meeting_code  text,
  title                  text NOT NULL DEFAULT '' CHECK (char_length(title) <= 200),
  template               text NOT NULL DEFAULT 'general'
                         CHECK (template IN ('general', 'standup', 'client_call', 'interview', 'one_on_one')),
  started_at             timestamptz NOT NULL,
  ended_at               timestamptz,
  status                 text NOT NULL DEFAULT 'recording'
                         CHECK (status IN ('recording', 'processing', 'ready', 'updated', 'failed', 'too_short')),
  processing_step        text CHECK (processing_step IN ('finalizing', 'summarizing', 'validating', 'done')),
  -- Set during the undo grace period (FR-LIB, deletion_requests).
  deleted_at             timestamptz,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, workspace_id)
);
CREATE INDEX meetings_list_idx ON meetings (workspace_id, started_at DESC) WHERE deleted_at IS NULL;

CREATE TABLE participants (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL,
  meeting_id    text NOT NULL,
  display_name  text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 200),
  is_self       boolean NOT NULL DEFAULT false,
  source        text NOT NULL CHECK (source IN ('dom', 'user_edit')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE,
  UNIQUE (id, workspace_id)
);
CREATE INDEX participants_meeting_idx ON participants (meeting_id);

CREATE TABLE speaker_clusters (
  id              text PRIMARY KEY,
  workspace_id    text NOT NULL,
  meeting_id      text NOT NULL,
  lane            text NOT NULL CHECK (lane IN ('me', 'them')),
  -- The provider's cluster label within this meeting, e.g. "spk_2" (no cross-meeting identity).
  provider_label  text NOT NULL,
  participant_id  text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (participant_id, workspace_id) REFERENCES participants (id, workspace_id),
  UNIQUE (meeting_id, lane, provider_label),
  UNIQUE (id, workspace_id)
);

CREATE TABLE audio_assets (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL,
  meeting_id    text NOT NULL,
  lane          text NOT NULL CHECK (lane IN ('me', 'them', 'mixed')),
  storage_key   text NOT NULL UNIQUE,
  codec         text NOT NULL CHECK (codec IN ('opus', 'pcm16')),
  bytes         bigint NOT NULL CHECK (bytes >= 0),
  duration_ms   bigint NOT NULL CHECK (duration_ms >= 0),
  -- Retention (D-02): the retention job deletes the object and the row after this time.
  delete_after  timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE
);
CREATE INDEX audio_assets_meeting_idx ON audio_assets (meeting_id);
CREATE INDEX audio_assets_delete_after_idx ON audio_assets (delete_after) WHERE delete_after IS NOT NULL;

-- ADR-0011: one row per recorded part; the finalized playback MP4 gets its own row (part_id null).
CREATE TABLE video_assets (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL,
  meeting_id    text NOT NULL,
  part_id       text CHECK (part_id ~ '^vp_[0-9A-HJKMNP-TV-Z]{26}$'),
  status        text NOT NULL CHECK (status IN ('uploading', 'processing', 'ready', 'failed', 'expired')),
  mime_type     text NOT NULL CHECK (mime_type IN ('video/mp4', 'video/webm')),
  -- Session-clock start of the part (ARCHITECTURE §5.5), for click-to-seek.
  start_ms      bigint NOT NULL DEFAULT 0 CHECK (start_ms >= 0),
  duration_ms   bigint CHECK (duration_ms >= 0),
  fragments     integer CHECK (fragments >= 0),
  storage_key   text UNIQUE,
  bytes         bigint CHECK (bytes >= 0),
  delete_after  timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE,
  UNIQUE (meeting_id, part_id)
);
CREATE INDEX video_assets_delete_after_idx ON video_assets (delete_after) WHERE delete_after IS NOT NULL;

CREATE TABLE transcript_segments (
  id                  text PRIMARY KEY CHECK (id ~ '^seg_[0-9A-HJKMNP-TV-Z]{26}$'),
  workspace_id        text NOT NULL,
  meeting_id          text NOT NULL,
  lane                text NOT NULL CHECK (lane IN ('me', 'them')),
  speaker_cluster_id  text,
  start_ms            bigint NOT NULL CHECK (start_ms >= 0),
  end_ms              bigint NOT NULL,
  -- Display text (Roman for Hindi/Hinglish, D-01); raw_text is the provider's original output.
  text                text NOT NULL,
  raw_text            text NOT NULL,
  language            text NOT NULL,
  source              text NOT NULL CHECK (source IN ('live', 'batch')),
  words               jsonb,
  flags               text[] NOT NULL DEFAULT '{}'
                      CHECK (flags <@ ARRAY['echo', 'low_confidence']::text[]),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  CHECK (end_ms >= start_ms),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (speaker_cluster_id, workspace_id) REFERENCES speaker_clusters (id, workspace_id),
  UNIQUE (id, workspace_id)
);
CREATE INDEX transcript_segments_meeting_idx ON transcript_segments (meeting_id, start_ms);

CREATE TABLE notes (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL,
  meeting_id    text NOT NULL,
  text          text NOT NULL CHECK (char_length(text) BETWEEN 1 AND 2000),
  session_ms    bigint NOT NULL CHECK (session_ms >= 0),
  marker        text CHECK (marker IN ('decision', 'action', 'question', 'important')),
  "order"       integer NOT NULL DEFAULT 0,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE,
  UNIQUE (id, workspace_id)
);
CREATE INDEX notes_meeting_idx ON notes (meeting_id, "order");

-- ---------- summaries ----------

CREATE TABLE summaries (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL,
  meeting_id    text NOT NULL,
  version       integer NOT NULL CHECK (version >= 1),
  template      text NOT NULL
                CHECK (template IN ('general', 'standup', 'client_call', 'interview', 'one_on_one')),
  language      text NOT NULL,
  model         text NOT NULL,
  status        text NOT NULL CHECK (status IN ('pending', 'ready', 'failed')),
  overview      text,
  accepted      boolean NOT NULL DEFAULT false,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE,
  UNIQUE (meeting_id, version),
  UNIQUE (id, workspace_id)
);

CREATE TABLE summary_items (
  id                    text PRIMARY KEY,
  workspace_id          text NOT NULL,
  summary_id            text NOT NULL,
  kind                  text NOT NULL
                        CHECK (kind IN ('anchor_detail', 'decision', 'action_item', 'question', 'topic')),
  text                  text NOT NULL,
  anchor_note_id        text,
  -- Owners come from the participant list or stay null ("unassigned", AGENTS §3 rule 7).
  owner_participant_id  text,
  due_date              date,
  due_phrase            text,
  status                text CHECK (status IN ('open', 'done')),
  completed_at          timestamptz,
  user_edited           boolean NOT NULL DEFAULT false,
  flagged               boolean NOT NULL DEFAULT false,
  "order"               integer NOT NULL DEFAULT 0,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  -- Open/done applies to action items only (PRD §13).
  CHECK ((kind = 'action_item') = (status IS NOT NULL)),
  FOREIGN KEY (summary_id, workspace_id) REFERENCES summaries (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (anchor_note_id, workspace_id) REFERENCES notes (id, workspace_id) ON DELETE SET NULL (anchor_note_id),
  FOREIGN KEY (owner_participant_id, workspace_id) REFERENCES participants (id, workspace_id)
    ON DELETE SET NULL (owner_participant_id),
  UNIQUE (id, workspace_id)
);
CREATE INDEX summary_items_summary_idx ON summary_items (summary_id, "order");
CREATE INDEX summary_items_open_actions_idx ON summary_items (workspace_id, created_at DESC)
  WHERE kind = 'action_item' AND status = 'open';

-- Citations map items to segment IDs we supplied; code maps IDs to times (AGENTS §3 rule 7).
CREATE TABLE citations (
  id               text PRIMARY KEY,
  workspace_id     text NOT NULL,
  summary_item_id  text NOT NULL,
  segment_id       text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (summary_item_id, workspace_id) REFERENCES summary_items (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (segment_id, workspace_id) REFERENCES transcript_segments (id, workspace_id) ON DELETE CASCADE,
  UNIQUE (summary_item_id, segment_id)
);
CREATE INDEX citations_segment_idx ON citations (segment_id);

-- ---------- workspace settings, logs and accounting ----------

CREATE TABLE glossary_terms (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  term          text NOT NULL CHECK (char_length(term) BETWEEN 1 AND 100),
  created_by    text REFERENCES users (id) ON DELETE SET NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, term)
);

CREATE TABLE consent_logs (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL,
  meeting_id    text NOT NULL,
  mode          text NOT NULL CHECK (mode IN ('one_click', 'automatic', 'off')),
  notice_sent   boolean NOT NULL,
  notice_text   text,
  sent_at       timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE
);
CREATE INDEX consent_logs_meeting_idx ON consent_logs (meeting_id);

CREATE TABLE feedback (
  id            text PRIMARY KEY,
  workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  target_type   text NOT NULL CHECK (target_type IN ('summary', 'summary_item', 'segment')),
  target_id     text NOT NULL,
  rating        smallint NOT NULL CHECK (rating BETWEEN -1 AND 1),
  comment       text CHECK (char_length(comment) <= 2000),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

-- AGENTS §3 rule 10: cost per meeting (STT minutes per lane, LLM tokens, storage).
CREATE TABLE usage_records (
  id                     text PRIMARY KEY,
  workspace_id           text NOT NULL,
  meeting_id             text NOT NULL,
  stt_provider           text,
  stt_seconds_me         numeric(12, 3) NOT NULL DEFAULT 0,
  stt_seconds_them       numeric(12, 3) NOT NULL DEFAULT 0,
  llm_model              text,
  input_tokens           bigint NOT NULL DEFAULT 0,
  output_tokens          bigint NOT NULL DEFAULT 0,
  storage_bytes          bigint NOT NULL DEFAULT 0,
  estimated_cost_usd     numeric(12, 6) NOT NULL DEFAULT 0,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (meeting_id, workspace_id) REFERENCES meetings (id, workspace_id) ON DELETE CASCADE
);
CREATE INDEX usage_records_meeting_idx ON usage_records (meeting_id);

-- Audit trail; kept after the target is gone, so no foreign key to the target.
CREATE TABLE deletion_requests (
  id             text PRIMARY KEY,
  workspace_id   text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  scope          text NOT NULL CHECK (scope IN ('meeting', 'account')),
  target_id      text NOT NULL,
  requested_at   timestamptz NOT NULL DEFAULT now(),
  execute_after  timestamptz NOT NULL,
  cancelled_at   timestamptz,
  completed_at   timestamptz,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX deletion_requests_due_idx ON deletion_requests (execute_after)
  WHERE cancelled_at IS NULL AND completed_at IS NULL;

-- ---------- updated_at and row-level security ----------

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'workspaces', 'users', 'memberships', 'user_settings', 'meetings', 'participants',
    'speaker_clusters', 'audio_assets', 'video_assets', 'transcript_segments', 'notes',
    'summaries', 'summary_items', 'citations', 'glossary_terms', 'consent_logs', 'feedback',
    'usage_records', 'deletion_requests'
  ] LOOP
    EXECUTE format(
      'CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated_at()',
      t || '_updated_at', t);
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
  END LOOP;

  FOREACH t IN ARRAY ARRAY[
    'memberships', 'user_settings', 'meetings', 'participants', 'speaker_clusters',
    'audio_assets', 'video_assets', 'transcript_segments', 'notes', 'summaries', 'summary_items',
    'citations', 'glossary_terms', 'consent_logs', 'feedback', 'usage_records', 'deletion_requests'
  ] LOOP
    EXECUTE format(
      'CREATE POLICY workspace_isolation ON %I USING (workspace_id = app_workspace_id()) '
      'WITH CHECK (workspace_id = app_workspace_id())', t);
  END LOOP;
END $$;

CREATE POLICY workspace_isolation ON workspaces
  USING (id = app_workspace_id()) WITH CHECK (id = app_workspace_id());

CREATE POLICY own_user ON users
  USING (google_sub = app_google_sub() OR id = app_user_id())
  WITH CHECK (google_sub = app_google_sub());

-- A user finds their workspaces before any workspace is selected.
CREATE POLICY own_memberships ON memberships FOR SELECT USING (user_id = app_user_id());

-- ---------- sign-in bootstrap ----------

-- First sign-in creates the user, a personal workspace (Phase 1: one per user), the owner
-- membership and default settings; later sign-ins update the profile. The application role owns
-- the tables and row security is forced, so there is no privileged path: the function sets the
-- transaction-local settings the policies above check. Call it in its own transaction (the
-- settings last until it ends). IDs are generated by the caller (ULIDs).
CREATE FUNCTION app_sign_in_google_user(
  p_google_sub text, p_email text, p_display_name text,
  p_new_user_id text, p_new_workspace_id text, p_new_membership_id text, p_new_settings_id text
) RETURNS TABLE (user_id text, workspace_id text, created boolean)
  LANGUAGE plpgsql
  SET search_path = public, pg_temp
  AS $$
DECLARE
  v_user text;
  v_workspace text;
BEGIN
  PERFORM set_config('app.google_sub', p_google_sub, true);
  SELECT u.id INTO v_user FROM users u WHERE u.google_sub = p_google_sub;
  IF v_user IS NOT NULL THEN
    UPDATE users SET email = p_email, display_name = p_display_name WHERE id = v_user;
    PERFORM set_config('app.user_id', v_user, true);
    SELECT m.workspace_id INTO v_workspace FROM memberships m
      WHERE m.user_id = v_user ORDER BY m.created_at LIMIT 1;
    RETURN QUERY SELECT v_user, v_workspace, false;
    RETURN;
  END IF;

  INSERT INTO users (id, google_sub, email, display_name)
    VALUES (p_new_user_id, p_google_sub, p_email, p_display_name);
  PERFORM set_config('app.workspace_id', p_new_workspace_id, true);
  INSERT INTO workspaces (id, name) VALUES (p_new_workspace_id, p_display_name);
  INSERT INTO memberships (id, workspace_id, user_id, role)
    VALUES (p_new_membership_id, p_new_workspace_id, p_new_user_id, 'owner');
  INSERT INTO user_settings (id, workspace_id, user_id)
    VALUES (p_new_settings_id, p_new_workspace_id, p_new_user_id);
  RETURN QUERY SELECT p_new_user_id, p_new_workspace_id, true;
END $$;
